import * as stylex from '@stylexjs/stylex';

const styles = stylex.create({
  base: { color: 'black' },
  alternate: { color: 'red' },
});

export function Section({ query, lowerQuery }) {
  const showAlternate = query.length > 0 && "documentation".startsWith(lowerQuery);

  return <section sx={[styles.base, showAlternate && styles.alternate]} />;
}

import * as stylex from '@stylexjs/stylex';

const VIEWS = ['grid', 'list'];

const styles = stylex.create({
  base: { color: 'black' },
  hview: { color: 'red' },
});

export function View({ hView }) {
  const isHView = VIEWS.includes(hView);

  return <div sx={[styles.base, isHView && styles.hview]} />;
}

import * as stylex from "@stylexjs/stylex";

const styles = stylex.create({
  base: { display: "block" },
  alternate: { borderTop: "none" },
});

export function Component({ query }) {
  const lowerQuery = query.toLowerCase();
  const showAlternate =
    query.length > 0 && "documentation".startsWith(lowerQuery);

  return (
    <section sx={[styles.base, showAlternate && styles.alternate]} />
  );
}

import * as stylex from "@stylexjs/stylex";

const VIEWS = ['grid', 'list'];
const SIZES = { small: 1 };

const styles = stylex.create({
  base: { color: 'black' },
  on: { color: 'red' },
});

export const Lower = ({ q }) => <i sx={[styles.base, q.toLowerCase() && styles.on]} />;
export const Join = ({ q }) => <i sx={[styles.base, VIEWS.join(q) && styles.on]} />;
export const Keys = ({ q }) => <i sx={[styles.base, Object.keys(SIZES).includes(q) && styles.on]} />;
export const Chain = ({ q }) => <i sx={[styles.base, "documentation".concat("s").startsWith(q) && styles.on]} />;
export const Optional = ({ q }) => <i sx={[styles.base, q?.startsWith("a") && styles.on]} />;
export const Unknown = ({ q }) => <i sx={[styles.base, q.somethingUnknown() && styles.on]} />;
export const Constructed = ({ q }) => <i sx={[styles.base, new Set(VIEWS).has(q) && styles.on]} />;

import * as stylex from "@stylexjs/stylex";

const VIEWS = ['grid', 'list'];

const styles = stylex.create({
  base: { color: 'black' },
  on: { color: 'red' },
});

export function Some({ q }) {
  const matches = VIEWS.some(v => v === q);

  return <i sx={[styles.base, matches && styles.on]} />;
}

import * as stylex from '@stylexjs/stylex';

export const styles = stylex.create({
  plain: { content: "abc".length },
  empty: { content: "".length },
  arithmetic: { width: "abcd".length * 2 },
  computed: { content: "abc"["length"] },
  folded: { content: `ab${"c"}`.length },
  concatenated: { content: "abc".concat("de").length },
});

import * as stylex from '@stylexjs/stylex';

export const styles = stylex.create({
  astral: { content: "\u{1F600}a".length },
  pair: { content: "\uD83D\uDE00".length },
  lone: { content: "\uD83D".length },
  combining: { content: "e\u0301".length },
  precomposed: { content: "\u00E9".length },
  cjk: { content: "\u65E5\u672C\u8A9E".length },
  nul: { content: "a\u0000b".length },
});

import * as stylex from '@stylexjs/stylex';

const VIEWS = ['grid', 'list'];

export const styles = stylex.create({
  literal: { content: ["a", "b"].length },
  empty: { content: [].length },
  nested: { content: [[1, 2], [3]].length },
  trailing: { content: [1, 2,].length },
  binding: { content: VIEWS.length },
  arithmetic: { width: [1, 2, 3].length - 1 },
});

import * as stylex from '@stylexjs/stylex';

export const styles = stylex.create({
  hole: { content: [, 1].length },
});

import * as stylex from '@stylexjs/stylex';

export const styles = stylex.create({
  spread: { content: [...[1, 2]].length },
});

import * as stylex from '@stylexjs/stylex';

export const styles = stylex.create({
  unknown: { content: "abc".foo ?? "red" },
  unknownOnArray: { content: ["a"].foo ?? "blue" },
});

import * as stylex from '@stylexjs/stylex';

export const styles = stylex.create({
  indexed: { content: "abc"[0] },
});

import * as stylex from '@stylexjs/stylex';

export const styles = stylex.create({
  rejected: {
    // Every property the property-specificity table refuses. None may
    // reach the stylesheet; `color` is here so the entry has a verdict to
    // read rather than agreement about nothing.
    all: '1px solid red',
    animation: '1px solid red',
    background: '1px solid red',
    border: '1px solid red',
    borderInline: '1px solid red',
    borderBlock: '1px solid red',
    borderTop: '1px solid red',
    borderInlineEnd: '1px solid red',
    borderRight: '1px solid red',
    borderBottom: '1px solid red',
    borderInlineStart: '1px solid red',
    borderLeft: '1px solid red',
    // The deprecated aliases, each an alias *of* one of the above.
    borderHorizontal: '1px solid red',
    borderVertical: '1px solid red',
    borderBlockStart: '1px solid red',
    borderBlockEnd: '1px solid red',
    borderStart: '1px solid red',
    borderEnd: '1px solid red',
    color: 'red',
  },
});
